return ['domain'=>'page-builder-sandwich','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'sr_RS','project-id-version'=>'page-builder-sandwich','pot-creation-date'=>'2026-09-26T07:20:41+00:00','po-revision-date'=>'2026-09-26T07:20:41+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Page Builder Sandwich'=>'Page Builder Sandwich','https://zinndigital.com/wordpress-plugins/page-builder-sandwich'=>'https://zinndigital.com/wordpress-plugins/page-builder-sandwich','The foundation release of the rebuilt Page Builder Sandwich: a settings and About screen, a footprint-free front-end output layer, and one sample content block.'=>'Inicijalno izdanje redizajniranog Page Builder Sandwich-a: ekran sa podešavanjima i O programu, izlazni sloj na korisničkoj strani bez SEO otiska i jedan uzorak sadržajnog bloka.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'AI provajderi','The makers of ChatGPT. A good all-rounder.'=>'Tvorci aplikacije ChatGPT. Dobar svestrani uređaj.','The makers of Claude. Strong at writing and careful reasoning.'=>'Kreatori modela Claude. Snažan u pisanju i pažljivom zaključivanju.','Google\'s Gemini models. Fast and inexpensive.'=>'Gemini modeli kompanije Google. Brzi i povoljni.','A European AI company with fast, inexpensive models.'=>'Evropska kompanija za veštačku inteligenciju sa brzim i povoljnim modelima.','Low-cost models that are good at writing and code.'=>'Modeli poniske cene koji su dobri za pisanje i kodiranje.','One key for models from many different providers.'=>'Jedan ključ za modele od mnogo različitih provajdera.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Bilo koja usluga koja radi kao OpenAI API, uključujući model koji se pokreće na vašem sopstvenom računaru ili serveru.','General (used when nothing more specific is set)'=>'Opšte (koristi se kada nije podešeno ništa specifičnije)','Writing and rewriting'=>'Pisanje i prepisivanje','Translation'=>'Prevod','Code and CSS'=>'Kod i CSS','Sorry, you are not allowed to access this page.'=>'Žao nam je, nemate pristup ovoj stranici.','These settings are shared by every plugin that uses them: %s.'=>'Ova podešavanja deli svaki dodatak koji ih koristi: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Vaši ključevi su šifrovani u bazi podataka ovog sajta i šalju se samo i isključivo provajderu kojeg ste izabrali — nikada nama.','Step 1 of 2: choose an AI provider'=>'Korak 1 od 2: izaberite AI provajdera','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Vi unosite sopstveni ključ, tako da provajderu plaćate direktno ono što potrošite. Niste sigurni? Bilo koja od ovih opcija dobro funkcionisane; kasnije možete dodati još.','Next'=>'Sledeće','Step 2 of 2: connect %s'=>'Korak 2 od 2: povežite %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Unesite adresu vaše OpenAI-kompatibilne usluge, koja se završava sa /v1. Ključ je potreban samo ako ga usluga zatraži.','Open %s and sign in (or create a free account).'=>'Otvorite %s i prijavite se (ili kreirajte besplatan nalog).','the %s API keys page'=>'%s stranica sa API ključevima','Create a new key and copy it.'=>'Kreirajte novi ključ i kopirajte ga.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Nalepite ga ispod i pritisnite „Sačuvaj i testiraj“. Šaljemo jedan mali zahtev da proverimo da li radi.','Most providers need a little credit on the account before a key works: %s.'=>'Већини пружалаца услуга је потребан мали износ на рачуну пре него што кључ проради: %s.','add credit'=>'dodaj kredit','← Choose a different provider'=>'← Izaberite drugog provajdera','Address'=>'Adresa','Saved key ends in …%s — paste a new one to replace it'=>'Sačuvani ključ se završava sa …%s — nalepite novi da biste ga zamenili','Key (optional)'=>'Ključ (opciono)','API key'=>'API ključ','Save and test'=>'Sačuvaj i testiraj','Providers'=>'Provajderi','Provider'=>'Pružalac usluga','Status'=>'Статус','Key'=>'Ključ','Get a key'=>'Preuzmite ključ','Test'=>'Тест','Remove'=>'Ukloni','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Sačuvano novijom verzijom dodatka: ažurirajte ovaj dodatak ili ponovo unesite ključ.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Sačuvani ključ se više ne može otvoriti (bezbednosni ključevi sajta su promenjeni). Unesite ga ponovo.','Not connected'=>'Nije povezano','Connected — last test passed %s'=>'Povezano — poslednji test je uspeo %s','Last test failed: %s'=>'Poslednji test nije uspeo: %s','Connected — not tested yet'=>'Povezano — još nije testirano','Which model to use'=>'Koji model koristiti','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ označava našu preporuku za taj zadatak. Lista obuhvata svaki model koji vaš ključ može da koristi, a koja se učitava uživo od provajdera.','— Recommended for the provider —'=>'— Preporučeno za provajdera —','Save models'=>'Сачувај моделе','Refresh the model lists from the providers'=>'Osvežite liste modela od provajdera','best quality'=>'najbolji kvalitet','lowest cost'=>'najniža cena','fastest'=>'najbrže','Add a model yourself'=>'Dodajte model sami','A model came out today? Paste its exact name to use it straight away.'=>'Novi model je izašao danas? Nalepite njegov tačan naziv da biste ga odmah koristili.','Model name'=>'Naziv modela','Add model'=>'Додај модел','Recommended models list'=>'Lista preporučenih modela','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Lista preporučenih modela nije mogla biti verifikovana, tako da se preporuke ne prikazuju. Ponovo instalirajte dodatak ili uključite dnevna ažuriranja u nastavku.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Lista koja se koristi objavljena je %s. Svako ažuriranje dodatka donosi novu.','Also check Zinn Digital® once a day for an updated list.'=>'Takođe proverite Zinn Digital® jednom dnevno za ažuriranu listu.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Šalje se samo običan zahtev za preuzimanje: bez ključa, bez adrese sajta, ništa o vašem sadržaju. Lista je potpisana, a lista koja ne prođe provere potpisa se ignoriše.','Last checked %1$s: %2$s.'=>'Poslednja provera %1$s: %2$s.','Save, and check now if turned on'=>'Sačuvajte i proveri odmah ako je uključeno','a newer list was installed'=>'instalirana je novija lista','already up to date'=>'već je ažurirano','the download failed the signature check and was ignored'=>'preuzimanje nije uspelo proveru potpisa i zanemareno je','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® nije dostupan; trenutna lista ostaje u upotrebi','turned off'=>'isključen','Open'=>'Отвори','Check their status page'=>'Proverite njihovu stranicu sa statusom','Open your billing page'=>'Otvorite stranicu za naplatu','Open your API keys page'=>'Otvorite stranicu sa API ključevima','Open the AI settings'=>'Otvorite podešavanja veštačke inteligencije','Sorry, you are not allowed to do that.'=>'Žao nam je, nemate dozvolu za to.','Unknown provider.'=>'Nepoznati provajder.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Unesite adresu svoje usluge, na primer http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'To ne liči na API ključ. Kopirajte ga ponovo, bez razmaka.','Paste your API key first.'=>'Prvo nalepite svoj API ključ.','Key removed.'=>'Ključ je uklonjen.','Models saved.'=>'Modeli su sačuvani.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Unesite tačan naziv modela, na primer onako kako je navedeno u dokumentaciji provajdera.','Added %s. Choose it under "Which model to use".'=>'Dodato %s. Izaberite ga pod "Koji model koristiti".','Model removed.'=>'Model je uklonjen.','Daily updates are off. The list that came with the plugin is used.'=>'Dnevna ažuriranja su isključena. Koristi se lista koja je stigla uz dodatak.','Checked: %s.'=>'Označeno: %s.','Model lists refreshed.'=>'Liste modela su osvežene.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Vaš AI ključ je sačuvala novija verzija jednog od vaših dodataka. Ažurirajte ovaj dodatak ili ponovo unesite ključ u AI podešavanjima.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Vaš sačuvani AI ključ se više ne može otvoriti (bezbednosni ključevi sajta su promenjeni). Unesite ga ponovo u AI podešavanjima.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'AI još uvek nije podešen. Dodajte ključ za AI provajder u AI podešavanjima.','No model is chosen for this task. Pick one in the AI settings.'=>'Ni jedan model nije izabran za ovaj zadatak. Izaberite ga u AI podešavanjima.','That AI provider is not supported by this version of the plugin.'=>'Taj provajder veštačke inteligencije nije podržan od strane ove verzije dodatka.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Ovaj sajt nije mogao da pristupi vašem AI servisu. Proverite da li je pokrenut i da li je njegova adresa dostupna sa vašeg veb-servera (servis na vašem sopstvenom računaru nije dostupan sa hostovanog sajta).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Ovaj sajt nije mogao da uspostavi vezu sa adresom %s. Proverite njihovu stranicu statusa; ako rade, vaš provajder možda blokira odlazne veze ili je adresa pogrešna.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s navodi da vaš nalog nema preostalog kredita ili kvote. Dodajte kredit ili povećajte limit na svom nalogu kod njih, pa pokušajte ponovo.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s nije prihvatio vaš ključ. Možda je pogrešno unešen, opozvan ili je istekao. Kreirajte novi ključ i nalepite ga ovde.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s je odbio ovaj zahtev za vaš ključ. Ključ možda nema pristup ovom modelu ili funkciji, ili je vaš nalog potrebno verifikovati.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Model "%1$s" nije dostupan od %2$s za vaš ključ. Izaberite drugi model u podešavanjima za veštačku inteligenciju.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s ograničava brzinu kojom vaš ključ može da šalje zahteve. Sačekajte minut i pokušajte ponovo, ili povećajte ograničenje protoka kod njih.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s trenutno ima probleme (prekid rada ili preopterećenje sa njihove strane). Sa vašim podešavanjima je sve u redu. Pokušajte ponovo uskoro.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Zahtev za veštačku inteligenciju nije uspeo iz razloga koji nismo mogli da identifikujemo. Pokušajte ponovo; ako se to ponovi, obratite se podršci sa detaljima u nastavku.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Pružalac usluga veštačke inteligencije je odgovorio u obliku koji ovaj dodatak nije mogao da pročita. Pokušajte ponovo; ako se to nastavi, izaberite drugi model ili se obratite podršci.','Custom (OpenAI-compatible)'=>'Prilagođeno (kompatibilno sa OpenAI)','Save a key for this provider first.'=>'Prvo sačuvajte ključ za ovog provajdera.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Vaš ključ radi, ali provajder ne navodi nijedan model teksta za njega. Dodajte model sami u nastavku.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Povezano. %1$s se odazvao koristeći %2$s. Vaše AI funkcije su spremne za upotrebu.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Vaša korisnička uloga nema dozvolu za korišćenje veštačke inteligencije na ovom sajtu. Obratite se administratoru.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Ovaj sajt je dostigao mesečni limit potrošnje za veštačku inteligenciju. Administrator ga može povećati u podešavanjima za veštačku inteligenciju.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Ovaj sajt je dostigao mesečni limit AI zahteva. Administrator ga može povećati u AI podešavanjima.','Usage and cost'=>'Potrošnja i troškovi','The log, limits and role permissions apply to AI used through: %s.'=>'Dnevnik, ograničenja i dozvole uloga se primenjuju na veštačku inteligenciju koja se koristi preko: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Troškovi su približni, izračunati na osnovu objavljenih cena; model sa nepoznatom cenom računa se kao nula.','This month: %1$s requests, about %2$s.'=>'Ovog meseca: %1$s zahteva, oko %2$s.','When'=>'Kada','Who'=>'Ko','Used for'=>'Користи се за','Model'=>'Модел','Tokens in / out'=>'Tokeni (ulaz / izlaz)','About'=>'О нама','Result'=>'Rezultat','No AI requests have been made yet.'=>'Još uvek nisu upućeni nikakvi zahtevi ka veštačkoj inteligenciji.','Done'=>'Završeno','Limits and permissions'=>'Ograničenja i dozvole','Monthly spending limit (US dollars)'=>'Mesečni limit potrošnje (US dolara)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Ostavite prazno za bez ograničenja. Veštačka inteligencija se zaustavlja do kraja meseca kada približni trošak dostigne tu vrednost.','Monthly request limit'=>'Ограничење месечних захтева','Leave empty for no limit.'=>'Оставите празно за без ограничења.','Who may use AI'=>'Ko može da koristi veštačku inteligenciju','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Označite ništa da biste omogućili svima koji mogu da koriste funkcije dodatka da koriste veštačku inteligenciju. Administratori uvek mogu da je koriste.','Save limits and permissions'=>'Sačuvaj ograničenja i dozvole','Limits and permissions saved.'=>'Limiti i dozvole su sačuvani.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Skripte administratorskog ekrana nedostaju u ovoj kopiji dodatka. Ponovo je instalirajte iz objavljenog paketa.','This screen needs JavaScript.'=>'Ovaj ekran zahteva JavaScript.','Languages'=>'Jezici','Upgrade'=>'Nadogradite','Pricing'=>'Cene','Start Trial'=>'Započni probni period','Account'=>'Nalog','Contact Us'=>'Kontaktirajte nas','Affiliation'=>'Pripadnost','the kind of softwarePlugin'=>'Dodatak','greetingHey %s,'=>'Zdravo %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Prijavite se da primate imejl obaveštenja za bezbednosna i ažuriranja funkcija, edukativni sadržaj i povremene ponude, kao i da delite neke osnovne informacije o WordPress okruženju. Ovo će nam pomoći da %s učinimo kompatibilnijim sa vašim sajtom i boljim u obavljanju onoga za šta vam je potreban.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Prijavite se da primate obaveštenja putem e-pošte za bezbednosna i ažuriranja funkcija, edukativni sadržaj i povremene ponude, kao i da delite osnovne informacije o WordPress okruženju.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Ako ovo preskočite, u redu je! %1$s će i dalje raditi sasvim normalno.','Allow & Continue'=>'Dozvoli i nastavi','verbSkip'=>'Preskoči','Skipping, please wait'=>'Preskakanje, sačekajte','Continue'=>'Nastavi','Please wait'=>'Molimo sačekajte','as activating pluginActivating'=>'Aktiviranje','This will allow %s to'=>'Ovo će omogućiti da %s','Privacy Policy'=>'Politika privatnosti','Terms of Service'=>'Uslovi korišćenja','License Agreement'=>'Licencni ugovor','Have a license key?'=>'Imate ključ licence?','Activate License'=>'Aktiviraj licencu','View Basic Profile Info'=>'Pregledajte osnovne informacije profila','Your WordPress user\'s: first & last name, and email address'=>'Ime, prezime i adresa e-pošte vašeg WordPress korisnika','View Basic Website Info'=>'Pogledajte osnovne informacije o veb-sajtu','Homepage URL & title, WP & PHP versions, and site language'=>'URL i naslov početne strane, verzije WP-a i PHP-a, i jezik sajta','View Basic %s Info'=>'Pregledajte osnovne %s informacije','Current %s & SDK versions, and if active or uninstalled'=>'Trenutne %s i SDK verzije, i da li su aktivne ili deinstalirane','Newsletter'=>'Bilten','Updates, announcements, marketing, no spam'=>'Ažuriranja, obaveštenja, marketing, bez neželjene pošte','View Diagnostic Info'=>'Prikaži dijagnostičke informacije','WordPress & PHP versions, site language & title'=>'WordPress & PHP verzije, jezik i naziv sajta','View Plugins & Themes List'=>'Прикажи листу додатака и тема','Names, slugs, versions, and if active or not'=>'Nazivi, skraćeni nazivi (slugs), verzije i podatak da li su aktivni ili ne','optional'=>'opciono','Never miss an important update'=>'Nikada ne propustite važnu ispravku','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Uveli smo ovu opciju prijave kako nikada ne biste propustili važno ažuriranje i kako biste nam pomogli da učinimo %s kompatibilnijim sa vašim sajtom i efikasnijim u obavljanju onoga što vam je potrebno.','Thank you for updating to %1$s v%2$s!'=>'Hvala vam što ste ažurirali na %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Prefiks mora imati od 1 do 8 malih slova ili cifara, počinjati slovom i ne sme predstavljati naziv dodatka.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Izradio Neil Lock, izvršni direktor kompanije Zinn Digital® Ltd','Version %s'=>'Verzija %s','Page Builder Sandwich website'=>'Page Builder Sandwich veb-sajt','Zinn Digital® website'=>'Zinn Digital® veb-sajt','Settings saved.'=>'Podešavanja su sačuvana.','See the Pro plans and pricing'=>'Pogledajte Pro planove i cene','Front-end output'=>'Izlaz na front-endu','Class name prefix'=>'Prefiks imena klase','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Svako ime klase koje dodatak ispisuje na vašim stranicama počinje ovim prefiksom, tako da se na stranicama ne vidi koji je dodatak napravio. 1 do 8 malih slova ili cifara, počevši od slova.','Save'=>'Sačuvaj','Beta updates'=>'Бета ажурирања','This site receives beta versions as updates.'=>'Ovaj sajt prima beta verzije kao ažuriranja.','This site receives stable versions only.'=>'Ovaj sajt prima samo stabilne verzije.','Change this on the Account page'=>'Promenite ovo na stranici Nalog','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Beta verzije su dostupne licenciranim Pro instalacijama koje su povezane sa njihovim nalogom. Kada se povežete, možete se pridružiti sa stranice Nalog.','Content'=>'Садржај','Heading'=>'Naslov','Text'=>'Tekst','Style'=>'Stil','Plain'=>'Obično','Accent'=>'Акцент','No languages to switch between. The switcher appears when a translation plugin lists two or more languages.'=>'Nema jezika za prebacivanje. Prekidač se pojavljuje kada dodatak za prevod navede dva ili više jezika.','Switcher'=>'Prebacivač','Accessible label'=>'Pristupačna oznaka','Show the current language'=>'Prikaži trenutni jezik','block titleLanguage switcher (sample)'=>'Prekidač za jezik (primer)','block descriptionLists the site\'s languages from the translation plugin, when one is active. It renders nothing otherwise.'=>'Prikazuje jezike sajta iz dodatka za prevod, kada je aktivan. U suprotnom ne prikazuje ništa.','block keywordlanguage'=>'Jezik','block keywordswitcher'=>'prebacivač','block titleSample content'=>'Primer sadržaja','block descriptionA heading and a paragraph, rendered with neutral class names. It is the reference block for the translation contract.'=>'Naslov i pasus, ispisani sa neutralnim nazivima klasa. To je referentni blok za ugovor o prevođenju.','block keywordsample'=>'primer','block keywordtext'=>'текст']];